```js
/*!
 * SnakeGame.input —— 键盘输入映射（架构契约 v1 · §2.4）
 *
 * 职责：监听 window 的 keydown，把按键翻译为意图事件回调；
 *       输入层只产生意图（onStart / onDirection / onPauseToggle / onRestart），
 *       不直接修改游戏状态，反向过滤由 state.changeDirection 统一裁决。
 */
(function (root) {
  'use strict';

  var ns = root.SnakeGame = root.SnakeGame || {};

  // 方向键映射（冻结契约 §2.4）：ArrowUp|w|W → up 等。
  var DIRECTION_BY_KEY = {
    ArrowUp: 'up', w: 'up', W: 'up',
    ArrowDown: 'down', s: 'down', S: 'down',
    ArrowLeft: 'left', a: 'left', A: 'left',
    ArrowRight: 'right', d: 'right', D: 'right'
  };

  var ARROW_KEYS = { ArrowUp: true, ArrowDown: true, ArrowLeft: true, ArrowRight: true };

  function has(obj, key) {
    return Object.prototype.hasOwnProperty.call(obj, key);
  }

  function isSpaceKey(ev) {
    return ev.key === ' ' || ev.key === 'Spacebar' || ev.code === 'Space';
  }

  function safeInvoke(fn, arg) {
    if (typeof fn !== 'function') return;
    try { fn(arg); } catch (err) { /* 装配层负责错误兜底（§2.6），输入层不因回调异常中断监听 */ }
  }

  function attach(handlers) {
    handlers = handlers || {};
    var onDirection = handlers.onDirection;
    var onPauseToggle = handlers.onPauseToggle;
    var onRestart = handlers.onRestart;
    var onStart = handlers.onStart;

    // 待开始状态：首次方向/空格按压先触发 onStart；R 重开后回到待开始。
    var awaitingStart = true;
    var detached = false;

    function startIfNeeded() {
      if (!awaitingStart) return;
      awaitingStart = false;
      safeInvoke(onStart);
