/*!
 * SnakeGame.render —— Canvas 渲染与界面反馈（架构契约 v1 · §2.5）
 *
 * 只读 game 与最高分：绘制网格/蛇/食物、刷新分数面板、展示状态提示；
 * 不修改游戏状态、不推进逻辑，也不引用任何外部图片或字体。
 */
(function (root) {
  'use strict';

  var ns = root.SnakeGame = root.SnakeGame || {};

  var CELL = 24;               // 每格 24px
  var GRID = 20;               // 20×20 网格
  var SIZE = CELL * GRID;      // 画布 480×480

  var COLORS = {
    background: '#0b0f14',
    gridLine: 'rgba(148, 163, 184, 0.12)',
    border: 'rgba(148, 163, 184, 0.35)',
    snakeBody: '#22c55e',
    snakeHead: '#86efac',
    snakeEye: '#0b0f14',
    food: '#f97316',
    foodGlow: 'rgba(249, 115, 22, 0.5)'
  };

  var TEXT = {
    ready: '按方向键 / WASD 或空格开始游戏',
    paused: '已暂停 · 按 P 继续',
    over: '游戏结束'
  };

  function isFiniteNumber(value) {
    return typeof value === 'number' && isFinite(value);
  }

  function toNonNegInt(value) {
    var n = typeof value === 'number' ? value : Number(value);
    if (!isFinite(n) || n < 0) return 0;
    return Math.floor(n);
  }

  /**
   * createRenderer({canvas, scoreEl, highScoreEl, statusEl}) → renderer
   * renderer.draw(game, highScore) → void
   * renderer.setStatus(status, payload?) → void
   */
  function createRenderer(opts) {
    opts = opts || {};

    var canvas = opts.canvas || null;
    var scoreEl = opts.scoreEl || null;
    var highScoreEl = opts.highScoreEl || null;
    var statusEl = opts.statusEl || null;

    var ctx = null;
    if (canvas && typeof canvas.getContext === 'function') {
      try {
        ctx = canvas.getContext('2d');
      } catch (err) {
        ctx = null; // 无 2D 上下文时降级为仅刷新面板文本
      }
    }

    var dprApplied = 0;
    var lastGame = null;
    var lastHighScore = 0;

    // 按 devicePixelRatio 放大位图，保持逻辑坐标 480×480 不变（绘制更清晰）。
    function syncCanvasSize() {
      if (!ctx) return;
      var dpr = (root && isFiniteNumber(root.devicePixelRatio)) ? root.devicePixelRatio : 1;
      if (!(dpr > 0)) dpr = 1;
      if (dpr > 3) dpr = 3; // 上限，避免超高 DPR 生成过大位图

      if (dpr !== dprApplied) {
        dprApplied = dpr;
        canvas.width = Math.round(SIZE * dpr);
        canvas.height = Math.round(SIZE * dpr);
        if (canvas.style) {
          canvas.style.width = SIZE + 'px';
          canvas.style.height = SIZE + 'px';
        }
      }
      if (typeof ctx.setTransform === 'function') {
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      }
    }

    function updatePanel(el, value) {
      if (!el) return;
      var text = String(value);
      if (el.textContent !== text) el.textContent = text;
    }

    function drawBackground() {
      ctx.fillStyle = COLORS.background;
      ctx.fillRect(0, 0, SIZE, SIZE);

      ctx.strokeStyle = COLORS.gridLine;
      ctx.lineWidth = 1;
      ctx.beginPath();
      for (var i = 1; i < GRID; i += 1) {
        var p = i * CELL + 0.5; // 半像素对齐，避免网格线发虚
        ctx.moveTo(p, 0);
        ctx.lineTo(p, SIZE);
        ctx.moveTo(0, p);
        ctx.lineTo(SIZE, p);
      }
      ctx.stroke();

      ctx.strokeStyle = COLORS.border;
      ctx.strokeRect(0.5, 0.5, SIZE - 1, SIZE - 1);
    }

    function drawFood(food) {
      if (!food) return;
      var cx = (food.x + 0.5) * CELL;
      var cy = (food.y + 0.5) * CELL;
      var r = CELL * 0.32;

      ctx.save();
      ctx.shadowColor = COLORS.foodGlow;
      ctx.shadowBlur = 10;
      ctx.fillStyle = COLORS.food;
      ctx.beginPath();
      ctx.arc(cx, cy, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    function drawEyes(head, direction) {
      if (!head) return;
      var cx = (head.x + 0.5) * CELL;
      var cy = (head.y + 0.5) * CELL;
      var offset = CELL * 0.16; // 眼睛相对头心偏移
      var spread = CELL * 0.18; // 两眼间距
      var r = CELL * 0.09;
      var points;

      if (direction === 'left') {
        points = [[cx - offset, cy - spread], [cx - offset, cy + spread]];
      } else if (direction === 'right') {
        points = [[cx + offset, cy - spread], [cx + offset, cy + spread]];
      } else if (direction === 'down') {
        points = [[cx - spread, cy + offset], [cx + spread, cy + offset]];
      } else {
        // 'up' 或未指定方向
        points = [[cx - spread, cy - offset], [cx + spread, cy - offset]];
      }

      ctx.fillStyle = COLORS.snakeEye;
      for (var i = 0; i < points.length; i += 1) {
        ctx.beginPath();
        ctx.arc(points[i][0], points[i][1], r, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawSnake(snake, direction) {
      if (!snake || !snake.length) return;
      var w = CELL - 2;

      for (var i = snake.length - 1; i >= 0; i -= 1) {
        var seg = snake[i];
        if (!seg) continue;
        ctx.fillStyle = i === 0 ? COLORS.snakeHead : COLORS.snakeBody;
        ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, w, w);
      }

      drawEyes(snake[0], direction);
    }

    function draw(game, highScore) {
      lastGame = game || null;
      lastHighScore = toNonNegInt(highScore);

      if (ctx) {
        syncCanvasSize();
        drawBackground();
        if (game) {
          drawFood(game.food);
          drawSnake(game.snake, game.direction);
        }
      }

      updatePanel(scoreEl, game && isFiniteNumber(game.score) ? toNonNegInt(game.score) : 0);
      updatePanel(highScoreEl, lastHighScore);
    }

    function resolveOverScores(payload) {
      var score = null;
      var high = null;

      if (payload && typeof payload === 'object') {
        if (isFiniteNumber(payload.score)) score = payload.score;
        else if (payload.game && isFiniteNumber(payload.game.score)) score = payload.game.score;
        if (isFiniteNumber(payload.highScore)) high = payload.highScore;
      } else if (isFiniteNumber(payload)) {
        score = payload;
      }

      if (score === null) {
        score = (lastGame && isFiniteNumber(lastGame.score)) ? lastGame.score : 0;
      }
      if (high === null) high = lastHighScore;

      return { score: toNonNegInt(score), highScore: toNonNegInt(high) };
    }

    function setStatus(status, payload) {
      if (!statusEl) return;

      var text;
      if (status === 'ready') {
        text = TEXT.ready;
      } else if (status === 'paused') {
        text = TEXT.paused;
      } else if (status === 'over') {
